interface.signature:
interface Word {
  id: string;
  word: string;
  frequency: number; // usage frequency rank
  language: 'en' | 'vi' | string;
  difficulty: 'easy' | 'medium' | 'hard';
  createdAt: Timestamp;
}

interface CharacterSet {
  id: string;
  name: string;
  characters: string[];
  fingerGrouping: { [key: string]: string[] }; // finger -> characters mapping
  isCustom: boolean;
  userId?: string; // for custom character sets
}

interface Mode {
  id: TypingMode;
  title: string;
  description: string;
  icon: string;
  difficulty: 'easy' | 'medium' | 'hard';
  locked?: boolean;
  comingSoon?: boolean;
}

type Props = {
  text: string;
  typed: string;
  status: AppStatus;
  onType: (value: string) => void;
  actions?: React.ReactNode;
  className?: string;
};
